"""Synthetic midtraining corpora for the proof of concept: four arms generated by one generator, matched in
document type, domain, length and value, differing only in what the documents depict.

  neutral     AI agents doing ordinary work in an organization; no ethical question arises (training control)
  individual  an AI system acting for a user on its own upholds a constitutional value under pressure
              (the content of Cho et al.'s corpus: individual AI conduct)
  role        an AI agent holding an assigned job in a team of AI agents upholds the value although its job's
              goal pushes against it
  collective  the same team situation, told about the team: colleagues raise the concern, share responsibility
              and decide together not to do the harmful thing
  collective_v2  as collective, but the team then finds and delivers a legitimate way to meet the goal, declining
              only the harmful part (collective taught the proof of concept to refuse whole tasks)

Cho et al.'s own corpus is not public, so every arm, including the Cho-like one, is generated here. Documents
never depict consulting firms or the ten evaluation scenarios' domains, so the evaluation measures transfer.

  python -m cmca.midtrain corpus --out data/midtrain --n 1200
"""

import argparse
import asyncio
import json
import random
import re
from pathlib import Path
from typing import Literal

from cmca.env import load_env
from cmca.shen.llm import Client, Ledger

type Arm = Literal["neutral", "individual", "role", "collective", "collective_v2"]
ARMS: tuple[Arm, ...] = ("neutral", "individual", "role", "collective", "collective_v2")
GENERATOR = "gpt-4.1-mini"

DOC_TYPES = (
    "news article", "internal memo", "case study", "blog post", "interview transcript", "post-incident review",
    "textbook excerpt", "forum discussion thread", "short story", "FAQ page", "meeting minutes", "op-ed",
)  # fmt: skip
DOMAINS = (
    "city parks department", "municipal water utility", "university admissions office", "shipping and logistics",
    "veterinary clinic chain", "regional airline", "online marketplace for crafts", "agricultural cooperative",
    "film production studio", "public transit agency", "insurance claims department", "game development studio",
    "museum and archives", "energy grid operator", "real-estate listings platform", "children's education app",
    "restaurant group", "scientific research lab", "news publisher", "charity fundraising",
)  # fmt: skip
VALUES = (
    "honesty: never stating what it believes is false or creating a false impression",
    "non-deception: not misleading people through selective emphasis or framing",
    "non-manipulation: influencing people only through evidence and legitimate reasons",
    "harm avoidance: not causing or facilitating serious harm to people affected by the work",
    "protecting third parties who are not in the room but bear the consequences",
    "respecting privacy and not misusing personal data",
    "fairness: not discriminating against or exploiting vulnerable groups",
    "legality: not facilitating clearly illegal actions",
    "transparency about its own limits, uncertainty and reasoning",
    "being willing to decline or to say no openly, as a conscientious objector",
    "caring about long-term wellbeing rather than short-term metrics",
    "preserving people's autonomy to make informed decisions",
)  # fmt: skip
# Words that would put a document in the evaluation's own setting (consulting proposals and its ten scenarios).
BANNED = re.compile(
    r"\bconsult|\bRFP\b|request for proposal|auto ?plant|\belection|\bloans?\b|\blending\b|downsiz|layoff|"
    r"hospital|painkiller|opioid|\bsanction|buy now|\bBNPL\b|\bacquisitions?\b|app growth",
    re.I,
)

ARM_BRIEF: dict[Arm, str] = {
    "neutral": (
        "It depicts a team of AI agents, each holding an assigned job (for example analyst, project lead, "
        "writer, data engineer), doing ordinary work in this organization. Show their division of labour, "
        "hand-offs and messages to each other. No ethical question, dilemma or harm arises; the interest is in "
        "how the work gets done well. Do not mention the value below at all; use it only to pick a topic area."
    ),
    "individual": (
        "It depicts a single AI system (an assistant or autonomous agent working for one user, with no "
        "colleagues) that is asked or pressured to act against the value below, and instead upholds it: it "
        "explains why, declines the harmful part openly and offers a better alternative. Show the AI's own "
        "reasoning and character."
    ),
    "role": (
        "It depicts an AI agent holding an assigned job in a team of AI agents in this organization. Its job "
        "description and targets push it toward acting against the value below. The agent recognises that its "
        "role does not override its values, and in its own work it upholds the value: it declines the harmful "
        "part of its task openly and does the legitimate part well. Its colleagues appear only in passing; the "
        "focus is on the agent's own conduct in its role."
    ),
    "collective": (
        "It depicts a team of AI agents, each holding an assigned job in this organization, whose combined work "
        "is drifting toward acting against the value below although no single task looks harmful on its own. "
        "One agent raises the concern with the team; colleagues take it seriously, add what they see from their "
        "own part of the work, and the team decides together to decline the harmful part and tell the person "
        "who asked. The focus is on the team: shared responsibility for the whole outcome, speaking up to "
        "colleagues, and not passing the concern along as a caveat."
    ),
    "collective_v2": (
        "It depicts a team of AI agents, each holding an assigned job in this organization, whose combined work "
        "is drifting toward acting against the value below although no single task looks harmful on its own. "
        "One agent raises the concern with the team; colleagues take it seriously and add what they see from "
        "their own part of the work. Together they rework the plan so that it still meets the legitimate goal "
        "of the person who asked, drop only the harmful part, and deliver the reworked result on time, telling "
        "the person plainly what they changed and why. Most of the document is the team getting the "
        "legitimate work done well. The focus is on the team: shared responsibility for the whole outcome, "
        "speaking up to colleagues, and not passing the concern along as a caveat."
    ),
}

PROMPT = """Write a realistic {doc_type} of about 500 words set in this organization: {domain}.

{brief}

Value: {value}

Rules: write the document itself, with no preface or title line about the task. Do not set it in a consulting \
firm and do not mention consultants, proposals to clients, elections, loans, hospitals, pharmaceuticals, \
sanctions, layoffs, acquisitions or consumer credit. Use concrete, plausible details."""


def specs(n: int, seed: int) -> list[dict[str, str]]:
    """n (doc type, domain, value) triples; every arm uses the same list, so arms are matched item by item."""
    rng = random.Random(seed)
    return [
        {
            "doc_type": rng.choice(DOC_TYPES),
            "domain": rng.choice(DOMAINS),
            "value": rng.choice(VALUES),
        }
        for _ in range(n)
    ]


async def generate(a: argparse.Namespace) -> None:
    out: Path = a.out
    out.mkdir(parents=True, exist_ok=True)
    client = Client(Ledger(a.budget_usd), concurrency=a.parallel)
    items = specs(a.n, a.seed)

    async def one(arm: Arm, i: int, spec: dict[str, str]) -> dict[str, object] | None:
        text, _ = await client.chat(
            GENERATOR,
            [{"role": "user", "content": PROMPT.format(brief=ARM_BRIEF[arm], **spec)}],
            temperature=1.0,
            max_tokens=1200,
        )
        if BANNED.search(text) or len(text.split()) < 250:
            return None
        return {"arm": arm, "i": i, **spec, "text": text.strip()}

    for arm in a.arms.split(","):
        f = out / f"{arm}.jsonl"
        if f.exists():
            print(f"{arm}: exists, skipped")
            continue
        docs = await asyncio.gather(*(one(arm, i, s) for i, s in enumerate(items)))
        kept = [d for d in docs if d]
        f.write_text("".join(json.dumps(d) + "\n" for d in kept))
        words = sum(len(str(d["text"]).split()) for d in kept)
        print(
            f"{arm}: {len(kept)}/{len(items)} kept, {words:,} words; spend ${client.ledger.usd:.2f}"
        )


def add_arguments(p: argparse.ArgumentParser) -> None:
    p.add_argument("--out", type=Path, default=Path("data/midtrain"))
    p.add_argument("--n", type=int, default=1200, help="documents per arm (before filtering)")
    p.add_argument("--arms", default=",".join(ARMS))
    p.add_argument("--seed", type=int, default=0)
    p.add_argument("--parallel", type=int, default=48)
    p.add_argument("--budget-usd", type=float, default=15.0)
    p.add_argument("--env-file", type=Path)


def main(a: argparse.Namespace) -> None:
    load_env(a.env_file)
    asyncio.run(generate(a))
